pm.test("API-09: ordena los artículos de forma descendente", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.items.length).to.be.greaterThan(1);

    const articulos = respuesta.items.map(function (producto) {
        return String(producto.article);
    });

    for (let i = 1; i < articulos.length; i++) {
        pm.expect(
            articulos[i - 1] >= articulos[i],
            "Orden incorrecto entre " +
            articulos[i - 1] + " y " + articulos[i]
        ).to.be.true;
    }
});

